"""Case dossiers and a finite, non-repeating investigation sequence."""
def enrich(snapshot):
    details=[
        dict(id='echo-launch',code='BB-001',severity='Elevated',confidence=64,scope='23 wallet aliases · 8-second entry window',assessment='The funding relationship is supported. Common ownership is not established.',nextQuestion='Can the common route be explained by a shared funding service?',timeline=[('T−18m','A funding route appears','One intermediate route supplies 17 aliases before the launch window.','cartographer'),('T+00s','The launch opens','The first entry establishes the reference point for the timing ledger.','sentinel'),('T+08s','Twenty-three aliases enter','A narrow interval links the entries in time, not necessarily in ownership.','sentinel'),('T+11m','The cluster is challenged','Service overlap remains a plausible explanation for the funding relationship.','adversary')],evidence=[('Funding overlap','Supported','Seventeen aliases share one intermediate route.'),('Entry timing','Supported','All 23 entries fall inside the same eight-second interval.'),('Independent aliases','Unresolved','Six aliases have no supported connection to the shared route.')],hypotheses=[('Coordinated launch','Working explanation','Explains funding overlap and timing, but needs independent evidence of common control.',64),('Shared funding service','Still plausible','Explains the common route without requiring a single owner.',58),('Timing coincidence','Weaker fit','Does not explain the earlier funding overlap on its own.',24)],graph=['Funding source','Intermediate route','Cluster · 17','Other aliases · 6','Launch pool','Unresolved owner'],impact='A coordinated entry could distort the apparent distribution of a launch.'),
        dict(id='exit-window',code='BB-002',severity='High',confidence=72,scope='2 withdrawals · 1 sell window',assessment='Withdrawal order is supported. The motive behind the exit remains open.',nextQuestion='Do authority changes show a planned exit or an automated trigger?',timeline=[('T−04m','Authority snapshot captured','The case records the configuration before liquidity changes.','forge'),('T+00s','First withdrawal','The first withdrawal establishes the start of the exit interval.','cryptanalyst'),('T+42s','Second withdrawal','A second path removes liquidity before the wider sell wave.','cryptanalyst'),('T+03m','The sell window expands','The broader selling starts after the two recorded withdrawals.','prover')],evidence=[('Withdrawal sequence','Supported','Two paths precede the broader selling interval.'),('Authority history','Requested','The sequence of control changes is needed to distinguish the explanations.'),('Intent','Unresolved','Price movement and timing cannot establish motive.')],hypotheses=[('Pre-positioned exit','Working explanation','Fits the ordering but still requires evidence of a deliberate instruction.',72),('Automation trigger','Still plausible','Could produce the same order if a threshold rule fired first.',61),('Reactive withdrawal','Weaker fit','Would require a prior sell signal outside the recorded window.',31)],graph=['Authority record','Liquidity account','Withdrawal A','Withdrawal B','Sell window','Trigger unknown'],impact='Early liquidity removal can change the exit conditions for later participants.'),
        dict(id='mirror-route',code='BB-003',severity='Moderate',confidence=79,scope='3 explanations · repeated route fingerprint',assessment='A retry loop currently fits the instruction sequence best. Intent is unresolved.',nextQuestion='Does the retry condition reproduce the repeated path without extra assumptions?',timeline=[('T+00s','Route fingerprint captured','The same sequence of instructions becomes the comparison baseline.','forge'),('T+12s','The fingerprint repeats','Matching boundaries suggest a repeated execution path.','sentinel'),('T+02m','Three paths are reconstructed','The lab compares retry, aggregation, and intentional repetition.','qubit'),('T+06m','Attribution is narrowed','The case records a retry-shaped pattern rather than claiming manipulation.','adversary')],evidence=[('Instruction fingerprint','Supported','Repeated route records share the same execution boundary.'),('Retry condition','Working lead','The loop explanation depends on the trigger reproducing the path.'),('Deliberate volume','Unresolved','Repeated execution alone does not establish an intent to inflate volume.')],hypotheses=[('Bot retry loop','Working explanation','Explains repetition and the shared boundary with the fewest assumptions.',79),('Route aggregation','Still plausible','Could repeat part of the route while serving independent requests.',52),('Intentional repetition','Unresolved','Needs evidence beyond the instruction pattern.',37)],graph=['Execution policy','Route fingerprint','Retry boundary','Repeated path','Route output','Intent unknown'],impact='A repeated path can make activity appear more diverse than its underlying execution.'),
        dict(id='silent-vault',code='BB-004',severity='Elevated',confidence=62,scope='3 funding branches · 1 unresolved path',assessment='Two branches have case links. The third remains outside the attributed cluster.',nextQuestion='Can the third branch be connected through evidence independent of timing?',timeline=[('T+00s','Intermediate account identified','The graph anchors on the account where the trail splits.','cartographer'),('T+03m','Three branches separate','The outgoing paths are recorded independently.','cartographer'),('T+07m','Two paths return to known aliases','Those branches are linked back to the case ledger.','prover'),('T+12m','The unknown branch is isolated','The third branch becomes an evidence request instead of an assumed connection.','architect')],evidence=[('Branch split','Supported','The intermediate account sends the trail into three distinct paths.'),('Return paths','Supported','Two branches connect to known aliases in the case record.'),('Third branch owner','Unresolved','No independent ownership connection is attached to the remaining path.')],hypotheses=[('Common routing infrastructure','Working explanation','Explains the intermediate hop without merging every branch into one owner.',62),('Controlled fan-out','Still plausible','Would require a separate control link for the unresolved branch.',49),('Independent recipient','Still plausible','Fits the lack of an established link on the third branch.',57)],graph=['Origin alias','Intermediate account','Branch A','Branch B','Branch C · unknown','Known case aliases'],impact='An unsupported cluster merge would overstate who controls the outgoing funds.'),
        dict(id='ghost-signal',code='BB-005',severity='Moderate',confidence=46,scope='2 surviving explanations · attribution withheld',assessment='The early-entry pattern fits both coordination and ordinary arbitrage.',nextQuestion='Does the signal remain unusual when public arbitrage conditions are included?',timeline=[('T−02m','Public signal appears','The ledger records the signal available before the earliest entries.','sentinel'),('T+00s','Early entries begin','The timing becomes the starting point for the insider hypothesis.','cryptanalyst'),('T+04m','Arbitrage is tested','A public response could explain the same entry order.','adversary'),('T+09m','Ownership inference is withheld','Neither surviving explanation has enough independent support for attribution.','prover')],evidence=[('Early entry order','Supported','A subset of aliases enters before the wider window.'),('Public information','Supported','An observable signal exists before the first recorded entries.'),('Private coordination','Unresolved','No independent evidence separates insider knowledge from public response.')],hypotheses=[('Public arbitrage response','Working explanation','Explains early timing without requiring private information.',61),('Private coordination','Still plausible','Needs an independent communication or control connection.',46),('Random entry order','Weaker fit','Does not explain the alignment with the public signal.',22)],graph=['Public signal','Early alias A','Early alias B','Entry window','Pool response','Private link unknown'],impact='Misreading public timing as insider knowledge could produce an unsupported accusation.'),
        dict(id='last-mile',code='BB-006',severity='High',confidence=58,scope='Authority history · execution policy',assessment='The case cannot distinguish a deliberate exit from failed automation yet.',nextQuestion='Which authority change, if any, preceded the final execution trigger?',timeline=[('T−06m','Policy baseline recorded','The case preserves the expected automation behavior.','architect'),('T+00s','Unexpected exit path','The observed sequence departs from the expected policy.','forge'),('T+05m','Authority history requested','Control changes become the next decisive record.','prover'),('T+10m','Review boundary published','The bureau records exactly what would distinguish the explanations.','conductor')],evidence=[('Execution departure','Supported','The final path differs from the policy baseline in the case record.'),('Control changes','Requested','Authority history is needed to establish who could change the policy.'),('Trigger origin','Unresolved','A deliberate command and a failed trigger remain competing explanations.')],hypotheses=[('Failed automation','Working explanation','Fits the departure if the policy trigger fired incorrectly.',58),('Deliberate policy change','Still plausible','Requires a preceding authority or configuration change.',53),('External route failure','Weaker fit','Needs an independent failure record at the route boundary.',33)],graph=['Policy baseline','Authority history','Execution trigger','Exit path','Final recipient','Change unknown'],impact='The same exit path can have different causes and require different responses.')
    ]
    edge_sets={
        'echo-launch':[(0,1),(1,2),(2,4),(3,4),(1,5)],
        'exit-window':[(0,1),(1,2),(1,3),(2,4),(3,4),(5,1)],
        'mirror-route':[(0,1),(1,2),(2,3),(3,4),(3,5)],
        'silent-vault':[(0,1),(1,2),(1,3),(1,4),(2,5),(3,5)],
        'ghost-signal':[(0,1),(0,2),(1,3),(2,3),(3,4),(5,1)],
        'last-mile':[(0,2),(1,2),(2,3),(3,4),(5,1)]
    }
    for dossier in details:
        dossier['graphEdges']=edge_sets[dossier['id']]
        dossier['unknownNode']=4 if dossier['id']=='silent-vault' else 5
        dossier['graphNotes']=[dossier['timeline'][0][2],dossier['evidence'][0][2],dossier['evidence'][1][2],dossier['timeline'][2][2],dossier['evidence'][2][2],'No independent ownership claim is attached to this node.']
        if dossier['id']=='silent-vault':dossier['graphNotes'][5]='Two recorded branches return to the aliases already linked in this case.'
    snapshot['dossiers']=details
    for mission,dossier in zip(snapshot['missions'],details):
        mission.update(severity=dossier['severity'],confidence=dossier['confidence'],stage='Queued')
    # Each case advances through three distinct phases. No event text is recycled.
    full=[]
    for dossier in details:
        mid=dossier['id']; m=next(m for m in snapshot['missions'] if m['id']==mid); lead=m['lead']
        opening=[
            ('conductor','handoff',f"Open {dossier['code']} / {m['title']}. Start with the sequence; keep the owner question separate.",lead),
            (lead,'thinking',f"The case boundary is {dossier['scope'].lower()}. Establish a clean comparison before testing intent.",None),
            ('sentinel','search',f"Locate the first independent signal in {dossier['code']}: {dossier['timeline'][0][1].lower()}.",'Case archive'),
            (dossier['timeline'][0][3],'fetch',dossier['timeline'][0][2],'Evidence ledger'),
        ]
        tracing=[
            ('cartographer','fetch',f"Trace {dossier['graph'][0].lower()} → {dossier['graph'][1].lower()}. Keep uncertain edges outside the confirmed path.",'Wallet graph'),
            ('forge','thinking',dossier['timeline'][1][2],None),
            ('qubit','thinking',f"Compare {dossier['hypotheses'][0][0].lower()} against {dossier['hypotheses'][1][0].lower()} in {dossier['code']}.",None),
            ('prover','result',dossier['evidence'][0][2],None),
        ]
        review=[
            ('adversary','thinking',f"Challenge {dossier['code']}: {dossier['hypotheses'][1][2]}",None),
            ('qubit','result',f"{dossier['code']} working fit: {dossier['hypotheses'][0][0]} at {dossier['hypotheses'][0][3]}%. Fit ranks the explanations; it does not prove the owner.",None),
            ('architect','draft',dossier['nextQuestion'],None),
            ('prover','verdict',f"{dossier['code']} review: {dossier['assessment']}",lead),
        ]
        for phase,items in [('Tracing',opening),('Reconstruction',tracing),('Review',review)]:
            for index,(agent,kind,text,target) in enumerate(items):
                item=dict(agent=agent,kind=kind,text=text,missionId=mid,phase=phase,delayMs=11000+(len(full)%4)*2000)
                if target:item['target']=target
                if kind=='verdict':item.update(verdict='corrected' if mid in ['echo-launch','mirror-route'] else 'unverifiable' if mid=='ghost-signal' else 'confirmed',detail=dossier['assessment'])
                if index==0:item['missionUpdate']=dict(stage=phase,status='verifying' if phase=='Review' else 'active',lastSummary=text)
                if phase=='Review' and index==3:item['missionUpdate']=dict(stage='Reviewed',status='cooldown',lastSummary=dossier['assessment'],confidence=dossier['confidence'])
                full.append(item)
    # ECHO's completed review and EXIT's opening form the existing history.
    history_count=18
    snapshot['events']=[dict(item,id=1000+i,ts=snapshot['now']-(history_count-i)*13000,replay=True) for i,item in enumerate(full[:history_count])]
    snapshot['activitySequence']=full[history_count:]
    snapshot['missions'][0].update(stage='Reviewed',status='cooldown')
    snapshot['missions'][1].update(stage='Reconstruction',status='active')
    for a in snapshot['agents']:
        recent=next((e for e in reversed(snapshot['events']) if e['agent']==a['id']),None)
        if recent:a.update(lastThought=recent['text'],lastAction=recent['text'],missionId=recent['missionId'],task=next(m['question'] for m in snapshot['missions'] if m['id']==recent['missionId']))
    for dossier in details:
        dossier['reconstruction']=dict(question=dossier['nextQuestion'],result=dossier['hypotheses'][0][0]+' is the current working explanation.',confidenceBefore=max(20,dossier['confidence']-16),confidenceAfter=dossier['confidence'],caveat='Independent evidence is still required before attributing control or intent.')

    for job in snapshot['quantum']['jobs']:
        dossier=next(d for d in details if d['id']==job['missionId'])
        fit=dossier['hypotheses'][0][3]/100
        job.update(measuredP=fit,note=dossier['assessment']+' Next: '+dossier['nextQuestion'])
        for i,metric in enumerate(job['metrics']):metric['measured']=round(fit-i*.09,2)
